__NUXT_JSONP__("/inclusion/publicaciones/evidence_to_integrate_gender_perspective_in_disaster_risk_management_in_mexico", (function(a,b,c,d,e,f,g,h,i,j,k){return {data:[{post:{slug:"evidence_to_integrate_gender_perspective_in_disaster_risk_management_in_mexico",title:"Evidence to Integrate Gender Perspective in Disaster Risk Management in Mexico",date:"2025-10-14T17:25:28.004Z",img:"https:\u002F\u002Fucarecdn.com\u002F21a776b0-1697-4335-98bb-c95ebc391e83\u002F","img-alt":"Disaster Risk Management in Mexico",autor:"Ethos",category:e,extracto:"We want to generate quantitative evidence to measure and understand the differentiated impacts of disasters on women, including those related to gender-based violence, highlight the need to include this information in the National Disaster Risk Management strategies and share it with key stakeholders and * Promote evidence-based decision-making with a gender perspective in the development of DRM strategies.",file:"https:\u002F\u002Fucarecdn.com\u002Fe1ff98bf-bf12-48af-8385-f6abec559c7b\u002F",toc:[],body:{type:f,children:[{type:b,tag:d,props:{},children:[{type:a,value:"The objectives are:"}]},{type:a,value:c},{type:b,tag:"ul",props:{},children:[{type:a,value:c},{type:b,tag:i,props:{},children:[{type:a,value:"Generate quantitative evidence to measure and understand the differentiated impacts of disasters on women, including those related to gender-based violence (as one of the most frequently mentioned effects in the literature review)."}]},{type:a,value:c},{type:b,tag:i,props:{},children:[{type:a,value:"Highlight the need to include this information in the National Disaster Risk Management strategies and share it with key stakeholders."}]},{type:a,value:c},{type:b,tag:i,props:{},children:[{type:a,value:"Promote evidence-based decision-making with a gender perspective in the development of DRM strategies."}]},{type:a,value:c}]}]},dir:g,path:"\u002Fpublicaciones\u002Fevidence_to_integrate_gender_perspective_in_disaster_risk_management_in_mexico",extension:h,createdAt:"2025-11-25T01:24:03.288Z",updatedAt:"2025-11-25T01:24:03.289Z"},publicaciones:[{slug:"conectadas_al_cambio_por_un_trabajo_justo_para_las_mujeres_en_plataformas_digitales",title:"Conectadas al cambio: por un trabajo justo para las mujeres en plataformas digitales",date:"2026-01-29T21:30:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002Fb777d5d7-cd1f-4afd-b80b-6eb9e1011bc3\u002F","img-alt":"Por un trabajo justo para las mujeres en plataformas digitales",autor:"Ethos, Fundación Avina, ProDESC y Oxfam México",category:e,extracto:"El objetivo de este documento es analizar y evidenciar las barreras sistémicas que excluyen a las mujeres de este sector, con base en la experiencia directa de las trabajadoras. A través de la sistematización de entrevistas y talleres con colectivas de conductoras y repartidoras, se contrastan las propuestas de la reforma en materia de trabajo en plataformas digitales con la realidad cotidiana. El análisis muestra cómo la violencia de género, la opacidad de los algoritmos y la falta de una red de cuidados convierten la supuesta “flexibilidad laboral” en una fuente de precariedad para ellas. A partir de este diagnóstico, se presentan recomendaciones de política pública y buenas prácticas empresariales dirigidas a cerrar la brecha entre la ley y la realidad, para que la promesa del trabajo justo en la era digital sea, verdaderamente, para todas y todos. ",file:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F651cff88-f77e-4a4c-a59c-f8b0d6873e38\u002F",toc:[],body:{type:f,children:[{type:b,tag:d,props:{},children:[{type:a,value:"El objetivo de este documento es analizar y evidenciar las barreras sistémicas que excluyen a las mujeres de este sector, con base en la experiencia directa de las trabajadoras. A través de la sistematización de entrevistas y talleres con colectivas de conductoras y repartidoras, se contrastan las propuestas de la reforma en materia de trabajo en plataformas digitales con la realidad cotidiana. El análisis muestra cómo la violencia de género, la opacidad de los algoritmos y la falta de una red de cuidados convierten la supuesta “flexibilidad laboral” en una fuente de precariedad para ellas. A partir de este diagnóstico, se presentan recomendaciones de política pública y buenas prácticas empresariales dirigidas a cerrar la brecha entre la ley y la realidad, para que la promesa del trabajo justo en la era digital sea, verdaderamente, para todas y todos."}]}]},dir:g,path:"\u002Fpublicaciones\u002Fconectadas_al_cambio_por_un_trabajo_justo_para_las_mujeres_en_plataformas_digitales",extension:h,createdAt:"2026-07-19T00:56:17.268Z",updatedAt:"2026-07-19T00:56:17.269Z"},{slug:"cuando_el_desastre_golpea_distinto_mujeres_y_hombres_tras_el_huracan_otis",title:"Cuando el desastre golpea distinto: mujeres y hombres tras el huracán Otis",date:"2026-05-04T06:00:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F7aea98e9-3923-4f9f-8d26-f18231e79b35\u002F",autor:"Ethos, Centro Nacional de Prevención de Desastres ",category:e,extracto:"El huracán Otis evidenció cómo las desigualdades influyen en la preparación, los impactos y la recuperación tras un desastre.  Este informe analiza, desde una perspectiva de género e interseccionalidad, cómo mujeres, población indígena y afromexicana enfrentaron de forma diferenciada los efectos del huracán en Acapulco, y propone recomendaciones para construir respuestas más justas y efectivas.",file:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F12bb5aff-9368-40ac-b7c6-1d2866421317\u002F",toc:[],body:{type:f,children:[{type:b,tag:d,props:{},children:[{type:a,value:"El huracán Otis no solo dejó daños materiales sin precedentes en Acapulco: también evidenció y profundizó desigualdades estructurales que influyeron en la preparación, la experiencia durante la emergencia y las posibilidades de recuperación de la población."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Este informe presenta los hallazgos de una encuesta aplicada en Acapulco para analizar los impactos diferenciados del desastre entre mujeres y hombres, así como entre distintos grupos sociales. La evidencia muestra que factores como el género, el trabajo de cuidados y las condiciones de marginación influyen directamente en quién puede prepararse, quién enfrenta mayores riesgos y quién logra recuperarse."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"El documento ofrece recomendaciones para construir políticas de prevención, respuesta y recuperación más justas, resilientes y con perspectiva de género."}]}]},dir:g,path:"\u002Fpublicaciones\u002Fcuando_el_desastre_golpea_distinto_mujeres_y_hombres_tras_el_huracan_otis",extension:h,createdAt:j,updatedAt:j},{slug:"cuidados_para_la_primera_infancia_recomendaciones_hacia_la_conformacion_del_sistema_nacional_de_cuidados",title:"Cuidados para la primera infancia: Recomendaciones hacia la conformación del Sistema Nacional de Cuidados",date:"2025-03-18T14:41:00.000Z",img:"https:\u002F\u002Fucarecdn.com\u002Ffca2a0ef-b4dd-4e5f-9a7f-c17d24f27d70\u002F-\u002Fcrop\u002F1047x1377\u002F18,15\u002F-\u002Fpreview\u002F","img-alt":"Cuidados para la primera infancia",autor:"Ethos, Early Institute y el Centro de Investigación Económica y Presupuestaria ",category:e,extracto:"En este documento, se analiza el panorama actual del cuidado y se visibiliza su relevancia para la primera infancia, con el fin de generar recomendaciones para la creación, diseño, implementación y monitoreo de un Sistema Nacional de Cuidados con perspectiva de niñez. ",file:"https:\u002F\u002Fucarecdn.com\u002Fb2c423fb-64a1-42e7-9f85-07fff85a84e8\u002F",toc:[],body:{type:f,children:[{type:b,tag:d,props:{},children:[{type:a,value:"En este documento, se analiza el panorama actual del cuidado y se visibiliza su relevancia para la primera infancia, con el fin de generar recomendaciones para la creación, diseño, implementación y monitoreo de un Sistema Nacional de Cuidados con perspectiva de niñez."}]}]},dir:g,path:"\u002Fpublicaciones\u002Fcuidados_para_la_primera_infancia_recomendaciones_hacia_la_conformacion_del_sistema_nacional_de_cuidados",extension:h,createdAt:k,updatedAt:k}]}],fetch:{},mutations:[]}}("text","element","\n","p","inclusion","root","\u002Fpublicaciones",".md","li","2026-07-19T00:56:17.270Z","2025-04-23T06:21:15.398Z")));